inal_size\":67,\"final_size\":67,\"element\":{\"name\":\"amp-img\",\"attributes\":{\"width\":\"190\",\"height\":\"80\",\"src\":\"https:\\/\\/alura.test\\/wp-content\\/uploads\\/2025\\/06\\/Cooking-Up-logo1.png\",\"alt\":\"Logo Cookin\'Up\",\"class\":\"wp-image-63 amp-wp-enforced-sizes amp-wp-f4fa511\",\"layout\":\"intrinsic\",\"data-amp-original-style\":\"border-radius:0px;object-fit:cover\"}},\"origin\":\"style_attribute\",\"sources\":[{\"type\":\"theme\",\"name\":\"astra\",\"file\":\"inc\\/builder\\/markup\\/class-astra-builder-footer.php\",\"line\":132,\"function\":\"Astra_Builder_Footer::footer_markup\",\"hook\":\"astra_footer\",\"priority\":10},{\"type\":\"theme\",\"name\":\"astra\",\"file\":\"inc\\/builder\\/markup\\/class-astra-builder-footer.php\",\"line\":169,\"function\":\"Astra_Builder_Footer::primary_footer\",\"hook\":\"astra_primary_footer\",\"priority\":10},{\"type\":\"theme\",\"name\":\"astra\",\"file\":\"inc\\/builder\\/markup\\/class-astra-builder-footer.php\",\"line\":214,\"function\":\"Astra_Builder_Footer::render_column\",\"hook\":\"astra_render_footer_column\",\"priority\":10},{\"type\":\"core\",\"name\":\"wp-includes\",\"file\":\"widgets\\/class-wp-widget-block.php\",\"line\":59,\"function\":\"WP_Widget_Block::widget\",\"widget_id\":\"block-13\"}],\"priority\":70,\"hash\":\"270389d4cccae49c105e33ef576e62a5\",\"parse_time\":0.0005128383636474609375,\"shake_time\":1.9073486328125e-6,\"cached\":true,\"important_count\":0,\"kept_error_count\":0,\"preload_font_urls\":[],\"shaken_tokens\":[[true,{\".amp-wp-f4fa511:not(#_#_#_#_#_)\":true},[\"border-radius:0px\",\"object-fit:cover\"]]],\"included\":true},{\"group\":\"amp-custom\",\"original_size\":119,\"final_size\":119,\"element\":{\"name\":\"ul\",\"attributes\":{\"class\":\"wp-block-social-links aligncenter has-small-icon-size has-icon-background-color is-style-default is-content-justification-left is-layout-flex wp-container-core-social-links-is-layout-38479424 wp-block-social-links-is-layout-flex a