INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(607, 6, '2026-03-05 16:08:17', '2026-03-05 19:08:17', '{\n    \"sidebars_widgets[sidebar-1]\": {\n        \"value\": [\n            \"block-57\",\n            \"block-37\",\n            \"block-59\",\n            \"block-45\",\n            \"block-42\",\n            \"block-48\",\n            \"block-55\"\n        ],\n        \"type\": \"option\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-03-05 19:07:21\"\n    },\n    \"custom_css[astra]\": {\n        \"value\": \".ov-hd {\\n\\toverflow:hidden;\\n}\\n/*\\n * Post CSS: start\\n */\\n.ast-separate-container .ast-single-related-posts-container {\\n\\tborder-top:1px solid var(--ast-global-color-3);\\n}\\n\\n.post-navigation {\\n\\tdisplay:none;\\n}\\n/*\\n * Post CSS: end\\n */\\n\\n.cnt-image {\\n\\tdisplay:block;\\n\\tmargin:0 auto!important;\\n\\twidth:150px!important;\\n}\\n\\n.form-footer .wpcf7-response-output {\\n\\tdisplay:none;\\n}\\n\\n/*\\n * snippet_list_authors: start\\n */\\n.authors-list .items {\\n\\tdisplay:flex;\\n\\toverflow-x: auto;\\n\\tlist-style:none;\\n\\tgap:20px;\\n\\tmax-width:100%;\\n\\tjustify-content:center;\\n}\\n\\n.authors-list li {\\n\\twidth:100px;\\n\\tflex: 0 0 auto;\\n}\\n\\n.ast-single-post .entry-content .authors-list a {\\n\\ttext-decoration:none;\\n\\ttext-align:center;\\n}\\n\\n.authors-list img {\\n\\tdisplay:block;\\n\\twidth:150px;\\n\\tborder-radius:50%;\\n\\tmargin-bottom:20px;\\n}\\n\\n.authors-list p {\\n\\tmargin-bottom:0;\\n}\\n/*\\n * snippet_list_authors: end\\n */\\n\\n/*\\n * Author page: start\\n */\\n\\tbody .pp-multiple-authors-layout-boxed ul li {\\n\\t\\tpadding-top:64px;\\n\\t\\tpadding-bottom:0;\\n\\t}\\n\\n.ppma-page-title.page-title {\\n\\ttext-indent:-100px;\\n\\toverflow:hidden;\\n}\\n/*\\n * Author page: end\\n */\\n\\n.wp-block-latest-posts__featured-image {\\n\\tposition:relative;\\t\\n}\\n\\n.wp-block-latest-posts__list .icon-player {\\n\\tdisplay:block;\\n\\tborder-radius:50%;\\n\\twidth:50px;\\n\\theight:50px;\\n\\tbackground-color:#fff;\\n\\tposition:absolute;\\n\\ttop:50%;\\n\\tleft:50%;\\n\\ttransform: translate(-50%, -50%);\\n\\tbackground-color:rgba(255,255,255,0.4);\\n}\\n\\n.wp-block-latest-posts__list .icon-player:before {\\n\\tdisplay:block;\\n\\tcontent:\\\"\\\";\\n  width: 0; \\n  height: 0; \\n  border-top: 10px solid transparent;\\n  border-bottom: 10px solid transparent;\\n  border-left: 15px solid var(--ast-global-color-5);\\n\\tposition:absolute;\\n\\ttop:50%;\\n\\tleft:50%;\\n\\ttransform:translate(-35%, -50%);\\n}\\n\\n@media (min-width:768px) {\\n\\t\\t.ast-container #secondary .sidebar-main [id^=\\\"block\\\"].widget  {\\n\\t\\tpadding:0 0 0 10px;\\n\\t}\\n\\t\\n\\t.authors-list li {\\n\\t\\twidth:150px;\\n\\t}\\n}\\n\\n@media (min-width:1024px) {\\n\\t.cnt-image {\\n\\t\\twidth:400px!important;\\n\\t}\\t\\n\\n\\t/*\\n\\t * Author page: start\\n\\t */\\n\\tbody .pp-multiple-authors-layout-boxed ul li {\\n\\t\\talign-items:center;\\n\\t}\\n\\t.ppma-page-title.page-title {\\n\\t\\ttext-indent:-120px;\\n\\t}\\n\\t/*\\n\\t * Author page: end\\n\\t */\\n\\t\\n\\t.wp-block-latest-posts__list .icon-player {\\n\\t\\twidth:70px;\\n\\t\\theight:70px;\\n\\t}\\n\\n\\t.wp-block-latest-posts__list .icon-player:before {\\n\\t\\tborder-top: 20px solid transparent;\\n\\t\\tborder-bottom: 20px solid transparent;\\n\\t\\tborder-left: 30px solid var(--ast-global-color-5);\\n\\t}\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-03-05 19:07:21\"\n    },\n    \"widget_block[59]\": {\n        \"value\": {\n            \"raw_instance\": {\n                \"content\": \"<!-- wp:group {\\\"layout\\\":{\\\"type\\\":\\\"flex\\\",\\\"flexWrap\\\":\\\"nowrap\\\"}} -->\\n<div class=\\\"wp-block-group\\\"><!-- wp:paragraph -->\\n<p><a href=\\\"https://www.cookinup.com.br/wp-admin/themes.php\\\">Cancelar</a></p>\\n<!-- /wp:paragraph -->\\n\\n<!-- wp:latest-posts {\\\"displayFeaturedImage\\\":true,\\\"featuredImageAlign\\\":\\\"left\\\",\\\"featuredImageSizeWidth\\\":130,\\\"className\\\":\\\"ov-hd\\\"} /--></div>\\n<!-- /wp:group -->\"\n            }\n        },\n        \"type\": \"option\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-03-05 19:07:21\"\n    },\n    \"astra-settings[enable-comments-area]\": {\n        \"value\": true,\n        \"type\": \"option\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-03-05 19:08:17\"\n    },\n    \"astra-settings[comments-box-placement]\": {\n        \"value\": \"\",\n        \"type\": \"option\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-03-05 19:08:17\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'ea22767c-66a8-416c-8524-175ce3b816ff', '', '', '2026-03-05 16:08:17', '2026-03-05 19:08:17', '', 0, 'https://www.cookinup.com.br/?p=607', 0, 'customize_changeset', '', 0);
